def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]")
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }
    functions = {"SUM", "MIN", "MAX", "IF"}

    def parse(content):
        if not content.startswith("="):
            return ("number", int(content))

        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for token in token_pattern.findall(content[1:]):
            if token[0].isdigit():
                nodes.append(("number", int(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    name = operators.pop()
                    args = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append((name, args))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and operators[-1] in precedence:
                    top = operators[-1]
                    if precedence[top] < precedence[op]:
                        break
                    if precedence[top] == precedence[op] and op == "neg":
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    expressions = {name: parse(content) for name, content in cells.items()}
    values = {}
    active = set()

    def argument_nodes(arguments):
        for node in arguments:
            if node[0] != ":":
                yield node
                continue

            first = node[1][1]
            second = node[2][1]
            col_lo, col_hi = sorted((ord(first[0]), ord(second[0])))
            row_lo, row_hi = sorted((int(first[1:]), int(second[1:])))

            for row in range(row_lo, row_hi + 1):
                for col in range(col_lo, col_hi + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def apply_binary(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    for root in cells:
        if root in values:
            continue

        stack = [("evaluate", ("reference", root))]
        result = 0

        while stack:
            task = stack.pop()
            action = task[0]

            if action == "evaluate":
                node = task[1]
                kind = node[0]

                if kind == "number":
                    result = node[1]

                elif kind == "reference":
                    name = node[1]
                    if name in values:
                        result = values[name]
                    elif name not in expressions:
                        result = 0
                    elif name in active:
                        result = "#CYCLE!"
                    else:
                        active.add(name)
                        stack.append(("finish_cell", name))
                        stack.append(("evaluate", expressions[name]))

                elif kind == "neg":
                    stack.append(("negate",))
                    stack.append(("evaluate", node[1]))

                elif kind == "IF":
                    condition, then_branch, else_branch = node[1]
                    stack.append(("choose", then_branch, else_branch))
                    stack.append(("evaluate", condition))

                elif kind in ("SUM", "MIN", "MAX"):
                    iterator = argument_nodes(node[1])
                    stack.append(("aggregate_next", kind, iterator, None))

                else:
                    stack.append(("binary_left", kind, node[2]))
                    stack.append(("evaluate", node[1]))

            elif action == "finish_cell":
                name = task[1]
                values[name] = result
                active.remove(name)

            elif action == "negate":
                if not isinstance(result, str):
                    result = -result

            elif action == "binary_left":
                if not isinstance(result, str):
                    stack.append(("binary_right", task[1], result))
                    stack.append(("evaluate", task[2]))

            elif action == "binary_right":
                if not isinstance(result, str):
                    result = apply_binary(task[1], task[2], result)

            elif action == "choose":
                if not isinstance(result, str):
                    stack.append(("evaluate", task[1] if result else task[2]))

            elif action == "aggregate_next":
                _, kind, iterator, accumulated = task
                node = next(iterator, None)
                if node is None:
                    result = 0 if accumulated is None else accumulated
                else:
                    stack.append(("aggregate_value", kind, iterator, accumulated))
                    stack.append(("evaluate", node))

            elif action == "aggregate_value":
                if not isinstance(result, str):
                    _, kind, iterator, accumulated = task
                    if accumulated is None:
                        accumulated = result
                    elif kind == "SUM":
                        accumulated += result
                    elif kind == "MIN":
                        accumulated = min(accumulated, result)
                    else:
                        accumulated = max(accumulated, result)
                    stack.append(("aggregate_next", kind, iterator, accumulated))

    return {name: values[name] for name in cells}
